// Windows CI only: all clipboard data below is generated by this test.
using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Text;
using System.Text.RegularExpressions;
using System.Windows.Forms;
using AIClawComputerUse;

public static class TestClipboard {
    [DllImport("user32.dll")] static extern IntPtr GetClipboardData(uint format);
    [DllImport("user32.dll")] static extern bool OpenClipboard(IntPtr owner);
    [DllImport("user32.dll")] static extern bool CloseClipboard();
    [DllImport("user32.dll", CharSet=CharSet.Unicode)] static extern uint RegisterClipboardFormat(string name);
    [DllImport("kernel32.dll")] static extern UIntPtr GlobalSize(IntPtr data);
    [DllImport("kernel32.dll")] static extern IntPtr GlobalLock(IntPtr data);
    [DllImport("kernel32.dll")] static extern bool GlobalUnlock(IntPtr data);
    static void Check(bool ok, string message) { if (!ok) throw new Exception(message); }
    static byte[] Raw(string name) {
        Check(OpenClipboard(IntPtr.Zero), "Open test clipboard");
        try {
            var handle = GetClipboardData(RegisterClipboardFormat(name));
            Check(handle != IntPtr.Zero, "Missing " + name);
            var bytes = new byte[checked((int)GlobalSize(handle).ToUInt64())];
            var pointer = GlobalLock(handle); Check(pointer != IntPtr.Zero, "Lock " + name);
            try { Marshal.Copy(pointer, bytes, 0, bytes.Length); } finally { GlobalUnlock(handle); }
            return bytes;
        } finally { CloseClipboard(); }
    }
    static void Refused(Action action) {
        bool failed = false;
        try { action(); } catch { failed = true; }
        Check(failed, "Expected refusal");
    }
    public static void Run() {
        try {
            var data = new DataObject();
            data.SetData(DataFormats.UnicodeText, false, "original 中文 🌦️");
            data.SetData(DataFormats.Html, false, "<b>original HTML</b>");
            data.SetData("AIClaw binary fixture", false, new MemoryStream(new byte[] { 0, 255, 42, 0, 128 }));
            using (var bitmap = new Bitmap(3, 2)) {
                bitmap.SetPixel(1, 1, Color.FromArgb(255, 204, 51, 68));
                data.SetData(DataFormats.Bitmap, true, bitmap);
                Clipboard.SetDataObject(data, true);
            }
            var binary = Raw("AIClaw binary fixture"); var html = Raw(DataFormats.Html);
            var tx = new ClipboardTransaction("粘贴 中文 🌤️", "text");
            try { tx.VerifyCurrent(); Check(Clipboard.GetText() == "粘贴 中文 🌤️", "Unicode payload"); }
            finally { tx.Dispose(); }
            Check(tx.Restored && !tx.NewerCopyPreserved, "Restore receipt");
            Check(Clipboard.GetText() == "original 中文 🌦️", "Original text restored");
            Check(Raw("AIClaw binary fixture").SequenceEqual(binary), "Binary bytes restored");
            Check(Raw(DataFormats.Html).SequenceEqual(html), "HTML bytes restored");
            using (var image = new Bitmap(Clipboard.GetImage())) Check(image.GetPixel(1, 1).ToArgb() == Color.FromArgb(255, 204, 51, 68).ToArgb(), "Bitmap restored");
            const string fragment = "<p><b>加粗 🌦️</b> &amp; text</p>";
            using (var rich = new ClipboardTransaction(fragment, "html")) {
                rich.VerifyCurrent(); var bytes = Raw(DataFormats.Html); var header = Encoding.UTF8.GetString(bytes);
                int start = Int32.Parse(Regex.Match(header, @"StartFragment:(\d+)").Groups[1].Value);
                int end = Int32.Parse(Regex.Match(header, @"EndFragment:(\d+)").Groups[1].Value);
                Check(Encoding.UTF8.GetString(bytes, start, end-start) == fragment, "CF_HTML UTF-8 fragment offsets");
                Check(Clipboard.GetText().Contains("加粗 🌦️ & text"), "HTML plain-text fallback");
            }
            using (var newer = new ClipboardTransaction("temporary", "text")) {
                Clipboard.SetText("new user copy"); Refused(newer.VerifyCurrent); newer.Dispose();
                Check(newer.NewerCopyPreserved && !newer.Restored, "New copy receipt");
                Check(Clipboard.GetText() == "new user copy", "New copy retained");
            }
            Refused(() => new ClipboardTransaction("bad\0text", "text"));
            Refused(() => new ClipboardTransaction("text", "unknown"));
            Check(Clipboard.GetText() == "new user copy", "Invalid inputs do not replace clipboard");
            Native.ParentEnded = true;
            Refused(() => new ClipboardTransaction("cancelled", "text"));
            Native.ParentEnded = false;
            Check(Clipboard.GetText() == "new user copy", "Cancellation before replacement");
            var large = new DataObject(); large.SetData("AIClaw oversized fixture", false, new MemoryStream(new byte[17 * 1024 * 1024]));
            Clipboard.SetDataObject(large, true);
            Refused(() => new ClipboardTransaction("refused", "text"));
            Check(Raw("AIClaw oversized fixture").Length >= 17 * 1024 * 1024, "Oversized original retained");
            Clipboard.Clear();
            using (var empty = new ClipboardTransaction("empty original", "text")) { empty.VerifyCurrent(); empty.Dispose(); Check(empty.Restored, "Empty restore receipt"); }
            Check(Clipboard.GetDataObject().GetFormats().Length == 0, "Empty original restored");
            Console.WriteLine("Clipboard Unicode, HTML offsets, raw formats, bitmap, newer copy, cancellation and capacity passed");
        } finally { Native.ParentEnded = false; Clipboard.Clear(); ClipboardTransaction.Shutdown(); }
    }
}
